        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        from fractions import Fraction

def generator(rng):
    while True:
        a = 2
        b = rng.randint(-5, 5)
        k = rng.randint(-4, 4)
        num_terms = rng.randint(3, 7)
        m = k + num_terms - 1

        try:
            terms_float = [((n + b) * (n + b + 1) + a * a) / a for n in range(k, m + 1)]
            if not all(t == int(t) for t in terms_float):
                continue # Should not happen for a=2
            terms = [int(t) for t in terms_float]
        except OverflowError:
            continue

        if any(t <= 0 for t in terms):
            continue

        if len(set(terms)) != num_terms:
            continue

        numerator = (k + b) * (m + b + 1) + a * a
        denominator = a * num_terms

        if numerator == 0:
            continue

        cot_sum = Fraction(numerator, denominator)

        # Avoid trivial or overly simple answers
        if cot_sum.numerator <= 1 or cot_sum.denominator <= 1:
            continue
        if cot_sum.numerator == cot_sum.denominator:
            continue
        # Avoid large coefficients
        if cot_sum.denominator > 100:
            continue

        coeff = cot_sum.denominator

        shuffled_terms = list(terms)
        rng.shuffle(shuffled_terms)
        terms_list_str = ", ".join(map(str, shuffled_terms))

        return {
            "terms_list_str": terms_list_str,
            "coeff": coeff
        }

